<?php
/** Approved inventory intelligence admin view. */
defined( 'ABSPATH' ) || exit;
final class SSW_Intelligence_Admin {
	public function __construct(){add_action('admin_menu',array($this,'admin_menu'),24);}
	public function admin_menu(){add_submenu_page('sheet-stock-sync-woo',__('Inventory Intelligence','sheet-stock-sync-woo'),__('Inventory Intelligence','sheet-stock-sync-woo'),'manage_woocommerce','ssw-inventory-intelligence',array($this,'render_page'));}
	public function render_page(){if(!current_user_can('manage_woocommerce')){wp_die(esc_html__('Permission denied.','sheet-stock-sync-woo'));}$rows=$this->load_rows(200);?><div class="wrap"><h1><?php esc_html_e('Inventory Intelligence','sheet-stock-sync-woo');?></h1><p><?php esc_html_e('Forecasting, stockout risk, Revenue at Risk, Estimated Lost Sales, Inventory Health and expanded Slow / Dead Stock intelligence.','sheet-stock-sync-woo');?></p><?php if(!$rows):?><div class="notice notice-info inline"><p><?php esc_html_e('No precomputed product metrics are available yet.','sheet-stock-sync-woo');?></p></div><?php endif;?><table class="widefat striped"><thead><tr><th>Product</th><th>Stock / cover</th><th>Stockout</th><th>Revenue at Risk</th><th>Estimated Lost Sales</th><th>Health</th><th>Slow / Dead Stock</th><th>Tied-up capital</th><th>Suggested action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9">No data yet.</td></tr><?php endif;foreach($rows as $r):?><tr><td><strong><?php echo esc_html($r['name']);?></strong><br><code><?php echo esc_html($r['sku']);?></code><br><small><?php echo esc_html($r['confidence_state']);?></small></td><td><?php echo esc_html($this->number($r['available_quantity']));?> / <?php echo null===$r['days_of_stock']?'—':esc_html($this->number($r['days_of_stock']).' d');?></td><td><?php echo esc_html($r['projected_stockout_date']?:'—');?><br><small><?php echo esc_html($this->number($r['incoming_quantity']));?> incoming</small></td><td><?php echo wp_kses_post(wc_price($r['revenue_at_risk']));?><br><small><?php echo esc_html($this->number($r['shortage_units']));?> units</small></td><td><?php echo wp_kses_post(wc_price($r['estimated_lost_revenue']));?><br><small>Estimated · <?php echo esc_html($r['oos_days_30']);?> OOS days</small></td><td><?php echo null===$r['health']['score']?'—':esc_html($this->number($r['health']['score']).'/100');?><br><small><?php echo esc_html($r['health']['status']);?></small></td><td><?php echo esc_html($r['aging_label']);?><br><small><?php echo esc_html($r['days_since_last_sale']);?> days since sale</small></td><td><?php echo null===$r['tied_up_cost']?'—':wp_kses_post(wc_price($r['tied_up_cost']));?></td><td><strong><?php echo esc_html($r['suggested_action']);?></strong></td></tr><?php endforeach;?></tbody></table></div><?php}
	private function load_rows($limit){global $wpdb;$m=$wpdb->prefix.'ssw_product_metrics_daily';$snap=$wpdb->prefix.'ssw_inventory_snapshots_daily';$po=$wpdb->prefix.'ssw_purchase_orders';$pi=$wpdb->prefix.'ssw_purchase_order_items';$f=$wpdb->prefix.'ssw_forecasts';$sp=$wpdb->prefix.'ssw_supplier_products';$date=$wpdb->get_var("SELECT MAX(metric_date) FROM {$m}");if(!$date){return array();}$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$m} WHERE metric_date=%s ORDER BY weighted_velocity DESC LIMIT %d",$date,min(200,max(1,(int)$limit))),ARRAY_A);$out=array();foreach($rows as $metric){$id=absint($metric['product_id']);$product=wc_get_product($id);if(!$product){continue;}$relation=$wpdb->get_row($wpdb->prepare("SELECT cost FROM {$sp} WHERE product_id=%d AND is_preferred=1 LIMIT 1",$id),ARRAY_A);$cost=$relation&&null!==$relation['cost']?(float)$relation['cost']:null;$incoming=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(GREATEST(i.ordered_qty-i.received_qty,0)),0) FROM {$pi} i INNER JOIN {$po} p ON p.id=i.po_id WHERE i.product_id=%d AND p.status IN ('approved','ordered','shipped','partially_received')",$id));$forecast=$wpdb->get_var($wpdb->prepare("SELECT forecast_qty FROM {$f} WHERE product_id=%d AND horizon_days=30 ORDER BY generated_for_date DESC,FIELD(model_version,'seasonal_month_v1','weighted_velocity_v1') ASC LIMIT 1",$id));$forecast=null===$forecast?(float)$metric['weighted_velocity']*30:(float)$forecast;$risk=SSW_Inventory_Intelligence::revenue_at_risk($forecast,(float)$metric['available_quantity'],$incoming,(float)$metric['avg_realized_price']);$oos=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM (SELECT snapshot_date,SUM(quantity) qty FROM {$snap} WHERE product_id=%d AND snapshot_date>=DATE_SUB(%s,INTERVAL 29 DAY) AND snapshot_date<=%s GROUP BY snapshot_date HAVING qty<=0) oos",$id,$date,$date));$lost=SSW_Inventory_Intelligence::estimated_lost_sales((float)$metric['weighted_velocity'],$oos,(float)$metric['avg_realized_price']);$days=$metric['last_sale_date']?max(0,(int)floor((strtotime($date)-strtotime($metric['last_sale_date']))/DAY_IN_SECONDS)):9999;$health=SSW_Inventory_Intelligence::health_score(array('availability'=>$this->availability_score($metric),'excess_aging'=>$this->aging_score($days),'demand'=>$this->demand_score($metric),'margin'=>null));$qty=max(0,(float)$metric['available_quantity']);$tied=null===$cost?null:$qty*$cost;$action=$this->action($days,$qty,(float)$metric['weighted_velocity'],$risk['shortage_units']);$out[]=array('product_id'=>$id,'name'=>$product->get_name(),'sku'=>$product->get_sku(),'available_quantity'=>$qty,'days_of_stock'=>null===$metric['days_of_stock']?null:(float)$metric['days_of_stock'],'projected_stockout_date'=>$metric['projected_stockout_date'],'confidence_state'=>$metric['confidence_state'],'incoming_quantity'=>$incoming,'shortage_units'=>$risk['shortage_units'],'revenue_at_risk'=>$risk['revenue_at_risk'],'oos_days_30'=>$oos,'estimated_lost_revenue'=>$lost['estimated_lost_revenue'],'health'=>$health,'days_since_last_sale'=>$days,'aging_label'=>$this->aging_label($days),'tied_up_cost'=>$tied,'suggested_action'=>$action); }return $out;}
	private function action($days,$qty,$velocity,$shortage){if($shortage>0){return 'Replenish / review incoming stock';}if($qty<=0){return 'No excess stock';}if($days>180){return 'Clearance or bundle candidate';}if($days>90){return 'Stop/reduce reorder; markdown candidate';}if($days>60||$velocity<=0){return 'Review reorder level';}return 'Keep current policy';}
	private function availability_score($m){if((float)$m['available_quantity']<=0){return 0.0;}if(null===$m['days_of_stock']){return 70.0;}$d=(float)$m['days_of_stock'];if($d<7){return 20.0;}if($d<14){return 45.0;}if($d<30){return 75.0;}return 100.0;}
	private function aging_score($d){if($d<=30){return 100.0;}if($d<=60){return 75.0;}if($d<=90){return 50.0;}if($d<=180){return 25.0;}return 5.0;}
	private function aging_label($d){if($d<=30){return 'Healthy (0–30 days)';}if($d<=60){return 'Slow (31–60 days)';}if($d<=90){return 'Very slow (61–90 days)';}if($d<=180){return 'Dead (91–180 days)';}return 'Critical dead stock (180+ days)';}
	private function demand_score($m){if('insufficient_data'===$m['confidence_state']){return 40.0;}if((float)$m['weighted_velocity']<=0){return 20.0;}return 'low_confidence'===$m['confidence_state']?70.0:100.0;}
	private function number($v){return number_format_i18n((float)$v,2);}
}
